const sql = ['BEGIN;', 'DELETE FROM readings;', 'DELETE FROM events;'];
const text = String(msg.payload || '').replace(/^\uFEFF/, '');
for (const raw of text.split(/\r?\n/)) {
  const line = raw.trim();
  if (!line) continue;
  const parts = line.split(' ');
  const kind = parts.shift();
  const f = {};
  for (const part of parts) { const i = part.indexOf('='); if (i > 0) f[part.slice(0, i)] = part.slice(i + 1); }
  const n = Number.parseInt(f.n);
  if (!Number.isInteger(n)) continue;
  const t = n * 15;
  if (kind === 'DATA') {
    for (const sensor of ['s1','s2','s3']) { const v = Number(f[sensor]); if (Number.isFinite(v)) sql.push(`INSERT INTO readings(n,t_s,sensor,value) VALUES(${n},${t},'${sensor}',${v});`); }
  } else if (kind === 'EVENT' && ['THRESHOLD','NORMAL','FAULT'].includes(f.type)) {
    sql.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'${f.type}','Serial event');`);
  }
}
sql.push('COMMIT;');
msg.payload = sql.join('\n') + '\n';
return msg;
